1	/**
2	 * Backup System — GitHub-as-database
3	 *
4	 * Backs up ~/.claude/ (agents, memory, rules, commands, CLAUDE.md, config,
5	 * history, logs) to a private GitHub repo with:
6	 *   - Chokidar file watcher + 5-sec debounced commit
7	 *   - 15-minute safety-net commit
8	 *   - Local commit queue for offline resilience
9	 *   - PAT-based auth (token stored encrypted in config.json)
10	 *   - Preview-diff restore flow
11	 *
12	 * State and settings are persisted in config.json under `backup` key.
13	 */
14	
15	const fs = require('fs');
16	const path = require('path');
17	const os = require('os');
18	const crypto = require('crypto');
19	const simpleGit = require('simple-git');
20	const chokidar = require('chokidar');
21	
22	const HOME = os.homedir();
23	const CLAUDE_DIR = path.join(HOME, '.claude');
24	const BACKUP_REPO_DIR = path.join(CLAUDE_DIR, '.backups', 'repo');
25	const SNAPSHOTS_DIR = path.join(CLAUDE_DIR, '.backups', 'snapshots');
26	const BACKUP_STATE_PATH = path.join(CLAUDE_DIR, '.backups', 'state.json');
27	const QUEUE_PATH = path.join(CLAUDE_DIR, '.backups', 'queue.json');
28	
29	// Core paths to back up (relative to ~/.claude/)
30	const INCLUDE_PATHS = [
31	  'agents',
32	  'memory',
33	  'rules',
34	  'commands',
35	  'CLAUDE.md',
36	  'settings.json',
37	  'history',
38	  'logs',
39	];
40	
41	// Paths to always exclude (written to .gitignore inside backup repo)
42	const EXCLUDE_PATTERNS = [
43	  '.backups/',         // never back up the backup itself
44	  'node_modules/',
45	  '.DS_Store',
46	  '*.log.tmp',
47	  'caches/',
48	  '.git/',
49	];
50	
51	// Debounce timings
52	const COMMIT_DEBOUNCE_MS = 5000;      // 5 sec after last change
53	const SAFETY_NET_INTERVAL_MS = 15 * 60 * 1000; // 15 min catchall
54	
55	// Token encryption — derived from a stable machine-local key
56	function getMachineKey() {
57	  // Uses hostname + home dir as a weak-but-stable key derivation
58	  // For production: store a real secret in env var or OS keychain
59	  const seed = `${os.hostname()}-${os.homedir()}-claude-hub-backup-v1`;
60	  return crypto.createHash('sha256').update(seed).digest();
61	}
62	
63	function encryptToken(plaintext) {
64	  if (!plaintext) return '';
65	  const key = getMachineKey();
66	  const iv = crypto.randomBytes(12);
67	  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
68	  const enc = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
69	  const tag = cipher.getAuthTag();
70	  return `${iv.toString('base64')}:${tag.toString('base64')}:${enc.toString('base64')}`;
71	}
72	
73	function decryptToken(ciphertext) {
74	  if (!ciphertext) return '';
75	  try {
76	    const [ivB64, tagB64, encB64] = ciphertext.split(':');
77	    const key = getMachineKey();
78	    const iv = Buffer.from(ivB64, 'base64');
79	    const tag = Buffer.from(tagB64, 'base64');
80	    const enc = Buffer.from(encB64, 'base64');
81	    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
82	    decipher.setAuthTag(tag);
83	    return Buffer.concat([decipher.update(enc), decipher.final()]).toString('utf8');
84	  } catch {
85	    return '';
86	  }
87	}
88	
89	function ensureDir(dir) {
90	  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
91	}
92	
93	function loadState() {
94	  try {
95	    if (fs.existsSync(BACKUP_STATE_PATH)) {
96	      return JSON.parse(fs.readFileSync(BACKUP_STATE_PATH, 'utf-8'));
97	    }
98	  } catch {}
99	  return {
100	    lastBackupAt: null,
101	    lastBackupStatus: null,
102	    lastBackupError: null,
103	    commitCount: 0,
104	    lastCommitSha: null,
105	    nextSafetyNetAt: null,
106	  };
107	}
108	
109	function saveState(state) {
110	  ensureDir(path.dirname(BACKUP_STATE_PATH));
111	  fs.writeFileSync(BACKUP_STATE_PATH, JSON.stringify(state, null, 2));
112	}
113	
114	function loadQueue() {
115	  try {
116	    if (fs.existsSync(QUEUE_PATH)) {
117	      return JSON.parse(fs.readFileSync(QUEUE_PATH, 'utf-8'));
118	    }
119	  } catch {}
120	  return { pending: 0, lastFailedPush: null };
121	}
122	
123	function saveQueue(queue) {
124	  ensureDir(path.dirname(QUEUE_PATH));
125	  fs.writeFileSync(QUEUE_PATH, JSON.stringify(queue, null, 2));
126	}
127	
128	// Build a .gitignore for the backup repo
129	function writeGitignore() {
130	  const content = EXCLUDE_PATTERNS.join('\n') + '\n';
131	  fs.writeFileSync(path.join(BACKUP_REPO_DIR, '.gitignore'), content);
132	}
133	
134	// Sync ~/.claude/* (included paths only) into the backup repo.
135	// This mirrors files; we don't rsync metadata because git tracks them anyway.
136	function syncToRepo() {
137	  ensureDir(BACKUP_REPO_DIR);
138	
139	  for (const rel of INCLUDE_PATHS) {
140	    const src = path.join(CLAUDE_DIR, rel);
141	    const dest = path.join(BACKUP_REPO_DIR, rel);
142	
143	    if (!fs.existsSync(src)) {
144	      // Remove from repo if previously backed up
145	      if (fs.existsSync(dest)) {
146	        fs.rmSync(dest, { recursive: true, force: true });
147	      }
148	      continue;
149	    }
150	
151	    const stat = fs.statSync(src);
152	    if (stat.isFile()) {
153	      ensureDir(path.dirname(dest));
154	      fs.copyFileSync(src, dest);
155	    } else if (stat.isDirectory()) {
156	      copyDirMirror(src, dest);
157	    }
158	  }
159	
160	  writeGitignore();
161	}
162	
163	// Mirror src → dest, removing files in dest that no longer exist in src
164	function copyDirMirror(src, dest) {
165	  ensureDir(dest);
166	
167	  const srcEntries = new Set(fs.readdirSync(src));
168	  // Remove stale files in dest
169	  if (fs.existsSync(dest)) {
170	    for (const entry of fs.readdirSync(dest)) {
171	      if (!srcEntries.has(entry)) {
172	        fs.rmSync(path.join(dest, entry), { recursive: true, force: true });
173	      }
174	    }
175	  }
176	
177	  for (const entry of srcEntries) {
178	    if (entry === '.git') continue; // never copy git dirs
179	    const s = path.join(src, entry);
180	    const d = path.join(dest, entry);
181	    const st = fs.statSync(s);
182	    if (st.isFile()) {
183	      fs.copyFileSync(s, d);
184	    } else if (st.isDirectory()) {
185	      copyDirMirror(s, d);
186	    }
187	  }
188	}
189	
190	// Generate a descriptive commit message from the git status
191	async function generateCommitMessage(git) {
192	  const status = await git.status();
193	  const added = status.not_added.length + status.created.length;
194	  const modified = status.modified.length;
195	  const deleted = status.deleted.length;
196	
197	  if (added + modified + deleted === 0) {
198	    return null; // nothing to commit
199	  }
200	
201	  // Highlight up to 3 notable files
202	  const notable = [
203	    ...status.modified.slice(0, 2),
204	    ...status.not_added.slice(0, 2),
205	    ...status.created.slice(0, 2),
206	  ]
207	    .slice(0, 3)
208	    .map((f) => path.basename(f));
209	
210	  const parts = [];
211	  if (modified > 0) parts.push(`~${modified}`);
212	  if (added > 0) parts.push(`+${added}`);
213	  if (deleted > 0) parts.push(`-${deleted}`);
214	
215	  const summary = parts.join(' ');
216	  const files = notable.length > 0 ? ` — ${notable.join(', ')}` : '';
217	  return `Auto-backup: ${summary}${files}`;
218	}
219	
220	// Get the loadConfig/saveConfig functions from server.js via injection
221	let _loadConfig = null;
222	let _saveConfig = null;
223	
224	function setConfigFns(loadFn, saveFn) {
225	  _loadConfig = loadFn;
226	  _saveConfig = saveFn;
227	}
228	
229	function getBackupConfig() {
230	  if (!_loadConfig) return null;
231	  const config = _loadConfig();
232	  return config.backup || null;
233	}
234	
235	function setBackupConfig(backupConfig) {
236	  if (!_loadConfig || !_saveConfig) return;
237	  const config = _loadConfig();
238	  config.backup = backupConfig;
239	  _saveConfig(config);
240	}
241	
242	// ──────────────────────────────────────────────────────────────────────────
243	//  Core backup operations
244	// ──────────────────────────────────────────────────────────────────────────
245	
246	async function initRepo(repoUrl, token) {
247	  ensureDir(BACKUP_REPO_DIR);
248	
249	  const git = simpleGit(BACKUP_REPO_DIR);
250	
251	  // Check if already a git repo
252	  const isRepo = await git.checkIsRepo().catch(() => false);
253	  if (!isRepo) {
254	    await git.init();
255	  }
256	
257	  // Set identity (required for commits)
258	  await git.addConfig('user.name', 'Polyglot Backup');
259	  await git.addConfig('user.email', 'backup@polyglot.local');
260	
261	  // Set or update remote with authenticated URL
262	  const authUrl = buildAuthenticatedUrl(repoUrl, token);
263	  const remotes = await git.getRemotes(true);
264	  const existing = remotes.find((r) => r.name === 'origin');
265	  if (existing) {
266	    await git.remote(['set-url', 'origin', authUrl]);
267	  } else {
268	    await git.addRemote('origin', authUrl);
269	  }
270	
271	  // Ensure we're on 'main' branch
272	  try {
273	    await git.checkoutLocalBranch('main');
274	  } catch {
275	    // Branch already exists, just check it out
276	    try {
277	      await git.checkout('main');
278	    } catch {}
279	  }
280	
281	  return git;
282	}
283	
284	function buildAuthenticatedUrl(repoUrl, token) {
285	  if (!token) return repoUrl;
286	  // Convert https://github.com/user/repo(.git) → https://<token>@github.com/user/repo.git
287	  try {
288	    const url = new URL(repoUrl);
289	    url.username = token;
290	    if (!url.pathname.endsWith('.git')) url.pathname += '.git';
291	    return url.toString();
292	  } catch {
293	    return repoUrl;
294	  }
295	}
296	
297	async function doBackup({ skipPush = false } = {}) {
298	  const cfg = getBackupConfig();
299	  if (!cfg || !cfg.enabled) {
300	    return { ok: false, error: 'Backup not configured or disabled' };
301	  }
302	  if (!cfg.repoUrl) {
303	    return { ok: false, error: 'No repo URL configured' };
304	  }
305	
306	  const state = loadState();
307	  const queue = loadQueue();
308	  const token = decryptToken(cfg.tokenEnc || '');
309	
310	  try {
311	    // 1. Mirror ~/.claude/* into repo dir
312	    syncToRepo();
313	
314	    // 2. Init/refresh git repo
315	    const git = await initRepo(cfg.repoUrl, token);
316	
317	    // 3. Stage all changes
318	    await git.add('./*');
319	    await git.add('.gitignore');
320	
321	    // 4. Generate message
322	    const message = await generateCommitMessage(git);
323	    if (!message) {
324	      // Nothing to commit — still try to push queued commits if any
325	      if (!skipPush && queue.pending > 0) {
326	        await pushQueued(git, cfg);
327	      }
328	      state.lastBackupAt = new Date().toISOString();
329	      state.lastBackupStatus = 'noop';
330	      saveState(state);
331	      return { ok: true, committed: false, pushed: queue.pending === 0 };
332	    }
333	
334	    // 5. Commit
335	    await git.commit(message);
336	    state.commitCount = (state.commitCount || 0) + 1;
337	    const log = await git.log(['-1']).catch(() => null);
338	    if (log?.latest?.hash) state.lastCommitSha = log.latest.hash;
339	
340	    // 6. Push
341	    let pushed = false;
342	    if (!skipPush) {
343	      try {
344	        await git.push(['-u', 'origin', 'main']);
345	        pushed = true;
346	        queue.pending = 0;
347	        queue.lastFailedPush = null;
348	      } catch (pushErr) {
349	        queue.pending = (queue.pending || 0) + 1;
350	        queue.lastFailedPush = {
351	          at: new Date().toISOString(),
352	          error: pushErr.message,
353	        };
354	      }
355	      saveQueue(queue);
356	    }
357	
358	    state.lastBackupAt = new Date().toISOString();
359	    state.lastBackupStatus = pushed ? 'pushed' : (skipPush ? 'committed' : 'queued');
360	    state.lastBackupError = null;
361	    saveState(state);
362	
363	    return { ok: true, committed: true, pushed, message };
364	  } catch (err) {
365	    state.lastBackupAt = new Date().toISOString();
366	    state.lastBackupStatus = 'error';
367	    state.lastBackupError = err.message;
368	    saveState(state);
369	    return { ok: false, error: err.message };
370	  }
371	}
372	
373	async function pushQueued(git, cfg) {
374	  const queue = loadQueue();
375	  try {
376	    await git.push(['-u', 'origin', 'main']);
377	    queue.pending = 0;
378	    queue.lastFailedPush = null;
379	    saveQueue(queue);
380	    return true;
381	  } catch (err) {
382	    queue.lastFailedPush = {
383	      at: new Date().toISOString(),
384	      error: err.message,
385	    };
386	    saveQueue(queue);
387	    return false;
388	  }
389	}
390	
391	// ──────────────────────────────────────────────────────────────────────────
392	//  File watcher + debounced commits + safety net
393	// ──────────────────────────────────────────────────────────────────────────
394	
395	let watcher = null;
396	let debounceTimer = null;
397	let safetyNetTimer = null;
398	let backupInProgress = false;
399	
400	function scheduleDebouncedBackup() {
401	  if (debounceTimer) clearTimeout(debounceTimer);
402	  debounceTimer = setTimeout(async () => {
403	    if (backupInProgress) return;
404	    backupInProgress = true;
405	    try {
406	      await doBackup();
407	    } finally {
408	      backupInProgress = false;
409	    }
410	  }, COMMIT_DEBOUNCE_MS);
411	}
412	
413	function startSafetyNet() {
414	  stopSafetyNet();
415	  safetyNetTimer = setInterval(async () => {
416	    if (backupInProgress) return;
417	    backupInProgress = true;
418	    try {
419	      await doBackup();
420	    } finally {
421	      backupInProgress = false;
422	    }
423	  }, SAFETY_NET_INTERVAL_MS);
424	}
425	
426	function stopSafetyNet() {
427	  if (safetyNetTimer) {
428	    clearInterval(safetyNetTimer);
429	    safetyNetTimer = null;
430	  }
431	}
432	
433	function startWatcher() {
434	  stopWatcher();
435	
436	  const watchTargets = INCLUDE_PATHS
437	    .map((rel) => path.join(CLAUDE_DIR, rel))
438	    .filter((p) => fs.existsSync(p));
439	
440	  if (watchTargets.length === 0) return;
441	
442	  watcher = chokidar.watch(watchTargets, {
443	    ignored: [
444	      /(^|[\/\\])\../, // dotfiles
445	      /node_modules/,
446	      /\.backups/,
447	      /\.git/,
448	    ],
449	    persistent: true,
450	    ignoreInitial: true,
451	    awaitWriteFinish: { stabilityThreshold: 500, pollInterval: 100 },
452	  });
453	
454	  watcher.on('all', () => scheduleDebouncedBackup());
455	}
456	
457	function stopWatcher() {
458	  if (watcher) {
459	    watcher.close();
460	    watcher = null;
461	  }
462	  if (debounceTimer) {
463	    clearTimeout(debounceTimer);
464	    debounceTimer = null;
465	  }
466	}
467	
468	function startBackupService() {
469	  const cfg = getBackupConfig();
470	  if (!cfg || !cfg.enabled || !cfg.repoUrl) {
471	    console.log('  Backup: not configured (see /backup in UI)');
472	    return;
473	  }
474	  startWatcher();
475	  startSafetyNet();
476	  console.log(`  Backup: enabled → ${cfg.repoUrl}`);
477	}
478	
479	function stopBackupService() {
480	  stopWatcher();
481	  stopSafetyNet();
482	}
483	
484	// ──────────────────────────────────────────────────────────────────────────
485	//  Restore — list history, preview diff, apply
486	// ──────────────────────────────────────────────────────────────────────────
487	
488	async function listCommits(limit = 50) {
489	  if (!fs.existsSync(path.join(BACKUP_REPO_DIR, '.git'))) return [];
490	  const git = simpleGit(BACKUP_REPO_DIR);
491	  try {
492	    const log = await git.log([`--max-count=${limit}`]);
493	    return log.all.map((c) => ({
494	      hash: c.hash,
495	      shortHash: c.hash.slice(0, 7),
496	      date: c.date,
497	      message: c.message,
498	      author: c.author_name,
499	    }));
500	  } catch {
501	    return [];
502	  }
503	}
504	
505	async function previewRestore(commitSha) {
506	  if (!fs.existsSync(path.join(BACKUP_REPO_DIR, '.git'))) {
507	    return { ok: false, error: 'No backup repo found' };
508	  }
509	  const git = simpleGit(BACKUP_REPO_DIR);
510	  try {
511	    // Diff between working copy and the target commit
512	    const diffSummary = await git.diffSummary([commitSha, 'HEAD']);
513	    const changes = diffSummary.files.map((f) => ({
514	      file: f.file,
515	      changes: 'changes' in f ? f.changes : 0,
516	      insertions: 'insertions' in f ? f.insertions : 0,
517	      deletions: 'deletions' in f ? f.deletions : 0,
518	      binary: f.binary,
519	    }));
520	    return { ok: true, commitSha, totalFiles: changes.length, changes };
521	  } catch (err) {
522	    return { ok: false, error: err.message };
523	  }
524	}
525	
526	async function applyRestore(commitSha) {
527	  if (!fs.existsSync(path.join(BACKUP_REPO_DIR, '.git'))) {
528	    return { ok: false, error: 'No backup repo found' };
529	  }
530	  const git = simpleGit(BACKUP_REPO_DIR);
531	  try {
532	    // 1. Checkout the target commit into the repo dir
533	    await git.checkout(commitSha);
534	
535	    // 2. Mirror repo files back into ~/.claude/ (the inverse of syncToRepo)
536	    for (const rel of INCLUDE_PATHS) {
537	      const src = path.join(BACKUP_REPO_DIR, rel);
538	      const dest = path.join(CLAUDE_DIR, rel);
539	      if (!fs.existsSync(src)) continue;
540	
541	      const st = fs.statSync(src);
542	      if (st.isFile()) {
543	        ensureDir(path.dirname(dest));
544	        fs.copyFileSync(src, dest);
545	      } else if (st.isDirectory()) {
546	        copyDirMirror(src, dest);
547	      }
548	    }
549	
550	    // 3. Return to main branch head so future backups continue
551	    await git.checkout('main').catch(() => {});
552	
553	    return { ok: true, commitSha };
554	  } catch (err) {
555	    return { ok: false, error: err.message };
556	  }
557	}
558	
559	// ──────────────────────────────────────────────────────────────────────────
560	//  Snapshot system — pre-edit file copies for automated agents
561	// ──────────────────────────────────────────────────────────────────────────
562	
563	const MAX_SNAPSHOTS = 500;
564	
565	function createSnapshot(targetPath, agentName = 'unknown') {
566	  try {
567	    if (!fs.existsSync(targetPath)) return null;
568	    ensureDir(SNAPSHOTS_DIR);
569	
570	    const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
571	    const rel = path.relative(CLAUDE_DIR, targetPath).replace(/[/\\]/g, '__');
572	    const snapName = `${ts}__${agentName}__${rel}`;
573	    const snapPath = path.join(SNAPSHOTS_DIR, snapName);
574	
575	    fs.copyFileSync(targetPath, snapPath);
576	    rotateSnapshots();
577	    return snapPath;
578	  } catch (err) {
579	    console.warn('Snapshot failed:', err.message);
580	    return null;
581	  }
582	}
583	
584	function rotateSnapshots() {
585	  try {
586	    if (!fs.existsSync(SNAPSHOTS_DIR)) return;
587	    const entries = fs.readdirSync(SNAPSHOTS_DIR)
588	      .map((name) => ({
589	        name,
590	        mtime: fs.statSync(path.join(SNAPSHOTS_DIR, name)).mtime.getTime(),
591	      }))
592	      .sort((a, b) => b.mtime - a.mtime); // newest first
593	
594	    if (entries.length <= MAX_SNAPSHOTS) return;
595	
596	    for (const old of entries.slice(MAX_SNAPSHOTS)) {
597	      fs.unlinkSync(path.join(SNAPSHOTS_DIR, old.name));
598	    }
599	  } catch {}
600	}
601	
602	function listSnapshots() {
603	  try {
604	    if (!fs.existsSync(SNAPSHOTS_DIR)) return [];
605	    return fs.readdirSync(SNAPSHOTS_DIR)
606	      .map((name) => {
607	        const full = path.join(SNAPSHOTS_DIR, name);
608	        const stat = fs.statSync(full);
609	        // Format: TS__agent__rel-path
610	        const parts = name.split('__');
611	        const ts = parts[0];
612	        const agent = parts[1];
613	        const rel = parts.slice(2).join('__').replace(/__/g, '/');
614	        return {
615	          name,
616	          ts,
617	          agent,
618	          relPath: rel,
619	          size: stat.size,
620	          mtime: stat.mtime.toISOString(),
621	        };
622	      })
623	      .sort((a, b) => b.mtime.localeCompare(a.mtime));
624	  } catch {
625	    return [];
626	  }
627	}
628	
629	function restoreSnapshot(snapshotName) {
630	  try {
631	    const snapPath = path.join(SNAPSHOTS_DIR, snapshotName);
632	    if (!fs.existsSync(snapPath)) {
633	      return { ok: false, error: 'Snapshot not found' };
634	    }
635	    const parts = snapshotName.split('__');
636	    const rel = parts.slice(2).join('__').replace(/__/g, '/');
637	    const dest = path.join(CLAUDE_DIR, rel);
638	    ensureDir(path.dirname(dest));
639	    fs.copyFileSync(snapPath, dest);
640	    return { ok: true, restoredTo: dest };
641	  } catch (err) {
642	    return { ok: false, error: err.message };
643	  }
644	}
645	
646	// ──────────────────────────────────────────────────────────────────────────
647	//  Public API
648	// ──────────────────────────────────────────────────────────────────────────
649	
650	function getStatus() {
651	  const cfg = getBackupConfig();
652	  const state = loadState();
653	  const queue = loadQueue();
654	  return {
655	    configured: !!(cfg && cfg.repoUrl),
656	    enabled: !!(cfg && cfg.enabled),
657	    repoUrl: cfg?.repoUrl || null,
658	    watchActive: !!watcher,
659	    lastBackupAt: state.lastBackupAt,
660	    lastBackupStatus: state.lastBackupStatus,
661	    lastBackupError: state.lastBackupError,
662	    commitCount: state.commitCount || 0,
663	    lastCommitSha: state.lastCommitSha,
664	    pendingQueue: queue.pending || 0,
665	    lastFailedPush: queue.lastFailedPush,
666	    includePaths: INCLUDE_PATHS,
667	    snapshotCount: listSnapshots().length,
668	    maxSnapshots: MAX_SNAPSHOTS,
669	  };
670	}
671	
672	async function connect({ repoUrl, token }) {
673	  if (!repoUrl || typeof repoUrl !== 'string') {
674	    return { ok: false, error: 'repoUrl is required' };
675	  }
676	  if (!token || typeof token !== 'string') {
677	    return { ok: false, error: 'GitHub PAT is required' };
678	  }
679	
680	  const tokenEnc = encryptToken(token);
681	  setBackupConfig({
682	    enabled: true,
683	    repoUrl: repoUrl.trim(),
684	    tokenEnc,
685	    connectedAt: new Date().toISOString(),
686	  });
687	
688	  // Try an initial backup to validate
689	  const result = await doBackup();
690	  if (!result.ok) {
691	    return { ok: false, error: `Connected but initial backup failed: ${result.error}` };
692	  }
693	
694	  // Start watcher + safety net now that we're live
695	  startBackupService();
696	
697	  return { ok: true, initialBackup: result };
698	}
699	
700	function disconnect() {
701	  const cfg = getBackupConfig();
702	  if (cfg) {
703	    setBackupConfig({ ...cfg, enabled: false });
704	  }
705	  stopBackupService();
706	  return { ok: true };
707	}
708	
709	module.exports = {
710	  setConfigFns,
711	  startBackupService,
712	  stopBackupService,
713	  getStatus,
