  type BackupSnapshot,
} from '../lib/api'
import { useApi } from '../hooks/useApi'
import { toast } from '../components/Toast'

type Tab = 'overview' | 'cloud' | 'snapshots'

function formatRelativeTime(iso: string | null): string {
  if (!iso) return 'never'
  const then = new Date(iso).getTime()
  const now = Date.now()
  const sec = Math.floor((now - then) / 1000)
  if (sec < 5) return 'just now'
  if (sec < 60) return `${sec}s ago`
  const min = Math.floor(sec / 60)
  if (min < 60) return `${min}m ago`
  const hr = Math.floor(min / 60)
  if (hr < 24) return `${hr}h ago`
  const day = Math.floor(hr / 24)
  return `${day}d ago`
}

function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`
  return `${(n / 1024 / 1024).toFixed(1)} MB`
}

export default function BackupPage() {
  const { data: status, refetch: refetchStatus, loading } = useApi(getBackupStatus)
  const [tab, setTab] = useState<Tab>('overview')

  // Auto-refresh status every 10 seconds
  useEffect(() => {
    const t = setInterval(refetchStatus, 10000)
    return () => clearInterval(t)
  }, [refetchStatus])

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64 text-text-muted">
        <Loader className="w-5 h-5 animate-spin mr-2" />
        Loading backup status...
      </div>
    )
  }

  if (!status) {
    return (
      <div className="p-8 text-red-400">Failed to load backup status</div>
    )
  }

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="px-8 pt-5 pb-4 shrink-0">
        <div className="flex items-center justify-between gap-4 flex-wrap">
          <div className="flex items-center gap-3">
            <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-accent/20 to-purple/20 ring-1 ring-accent/20 flex items-center justify-center">
              <CloudUpload className="w-5 h-5 text-accent" />
            </div>
            <div>
              <h1 className="text-xl font-bold leading-tight">Backup</h1>
              <p className="text-[11px] text-text-muted">
                Protect your agents, memory, and config against data loss
              </p>
            </div>
          </div>

          <HealthChip status={status} />
        </div>

        {/* Tab bar */}
        <div className="flex items-center gap-1 mt-5 bg-surface-2 p-0.5 rounded-lg w-fit">
          <TabButton active={tab === 'overview'} onClick={() => setTab('overview')}>
            <CloudUpload className="w-3.5 h-3.5" /> Overview
          </TabButton>
          <TabButton active={tab === 'cloud'} onClick={() => setTab('cloud')}>
            <History className="w-3.5 h-3.5" /> Cloud History
          </TabButton>
          <TabButton active={tab === 'snapshots'} onClick={() => setTab('snapshots')}>
            <Archive className="w-3.5 h-3.5" /> Local Snapshots
          </TabButton>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto px-8 pb-8">
        {tab === 'overview' && <OverviewTab status={status} onRefresh={refetchStatus} />}
        {tab === 'cloud' && <CloudHistoryTab status={status} onRefresh={refetchStatus} />}
        {tab === 'snapshots' && <SnapshotsTab onRefresh={refetchStatus} />}
      </div>
    </div>
  )
}

// ── Health chip ──────────────────────────────────────────────────────────────

function HealthChip({ status }: { status: BackupStatus }) {
  if (!status.configured) {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-amber-500/10 text-amber-400 text-xs font-semibold">
        <AlertTriangle className="w-3.5 h-3.5" />
        Not Configured
      </span>
    )
  }
  if (!status.enabled) {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-zinc-500/10 text-zinc-400 text-xs font-semibold">
        <Unplug className="w-3.5 h-3.5" />
        Paused
      </span>
    )
  }
  if (status.pendingQueue > 0) {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-amber-500/10 text-amber-400 text-xs font-semibold">
        <RefreshCw className="w-3.5 h-3.5" />
        {status.pendingQueue} Queued
      </span>
    )
  }
  if (status.lastBackupStatus === 'error') {
    return (
      <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-red-500/10 text-red-400 text-xs font-semibold">
        <X className="w-3.5 h-3.5" />
        Error
      </span>
    )
  }
  return (
    <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-emerald-500/10 text-emerald-400 text-xs font-semibold">
      <Check className="w-3.5 h-3.5" />
      Protected
    </span>
  )
}

function TabButton({ active, onClick, children }: {
  active: boolean
  onClick: () => void
  children: React.ReactNode
}) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-md transition-colors ${
        active ? 'bg-accent text-white shadow-sm shadow-accent/25' : 'text-text-muted hover:text-text'
      }`}
    >
      {children}
    </button>
  )
}

// ── Overview Tab ─────────────────────────────────────────────────────────────

function OverviewTab({ status, onRefresh }: { status: BackupStatus; onRefresh: () => void }) {
  const [connecting, setConnecting] = useState(false)
  const [running, setRunning] = useState(false)
  const [repoUrl, setRepoUrl] = useState('')
  const [token, setToken] = useState('')
  const [showConnectForm, setShowConnectForm] = useState(!status.configured)

  const handleConnect = async () => {

  const handleConnect = async () => {
    if (!repoUrl.trim() || !token.trim()) {
      toast('error', 'Repo URL and token are required')
      return
    }
    setConnecting(true)
    try {
      const res = await connectBackup(repoUrl.trim(), token.trim())
      if (!res.ok) {
        toast('error', res.error || 'Connection failed')
        return
      }
      toast('success', 'Backup connected successfully')
      setRepoUrl('')
      setToken('')
      setShowConnectForm(false)
      onRefresh()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Connection failed')
    } finally {
      setConnecting(false)
    }
  }

  const handleDisconnect = async () => {
    if (!confirm('Pause auto-backup? Your data stays backed up, but new changes won\'t be pushed until you reconnect.')) return
    try {
      await disconnectBackup()
      toast('success', 'Backup paused')
      onRefresh()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Failed to disconnect')
    }
  }

  const handleBackupNow = async () => {
    setRunning(true)
    try {
      const res = await runBackupNow()
      if (!res.ok) {
        toast('error', res.error || 'Backup failed')
        return
      }
      if (res.committed) {
        toast('success', res.pushed ? 'Backup pushed to GitHub' : 'Committed locally (push queued)')
      } else {
        toast('success', 'No changes to back up')
      }
      onRefresh()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Backup failed')
    } finally {
      setRunning(false)
    }
  }

  return (
    <div className="space-y-4 max-w-4xl">
      {/* Connect flow */}
      {showConnectForm && (
        <div className="bg-surface rounded-2xl border border-border overflow-hidden">
          <div className="px-5 py-3 border-b border-border bg-gradient-to-r from-accent/5 to-transparent">
            <div className="flex items-center gap-2.5">
              <GitBranch className="w-4 h-4 text-accent" />
              <h3 className="text-sm font-bold">Connect GitHub Repository</h3>
            </div>
          </div>
          <div className="px-5 py-5 space-y-4">
            <div className="bg-accent/5 border border-accent/20 rounded-lg px-4 py-3 text-xs text-text-secondary space-y-2">
              <div className="flex items-start gap-2">
                <Info className="w-3.5 h-3.5 text-accent shrink-0 mt-0.5" />
                <div className="flex-1 space-y-1.5">
                  <p className="font-semibold text-text">Setup steps:</p>
                  <ol className="list-decimal list-inside space-y-0.5 text-[11px]">
                    <li>Go to <a href="https://github.com/new" target="_blank" rel="noopener noreferrer" className="text-accent underline">github.com/new</a> → create a <strong>private</strong> repo (e.g. <code className="text-[10px] bg-surface-2 px-1 rounded">polyglot-backup</code>)</li>
                    <li>Copy the HTTPS clone URL</li>
                    <li>Go to <a href="https://github.com/settings/tokens?type=beta" target="_blank" rel="noopener noreferrer" className="text-accent underline">Settings → Developer → Tokens</a> → create a fine-grained PAT with <strong>Repo: Read + Write</strong> access</li>
                    <li>Paste both below</li>
                  </ol>
                </div>
              </div>
            </div>

            <div>
              <label className="text-[11px] font-semibold text-text-muted uppercase tracking-wider block mb-1.5">
                Repository URL
              </label>
              <input
                value={repoUrl}
                onChange={(e) => setRepoUrl(e.target.value)}
                placeholder="https://github.com/yash/polyglot-backup.git"
                className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/10"
              />
            </div>

            <div>
              <label className="text-[11px] font-semibold text-text-muted uppercase tracking-wider block mb-1.5">
                Personal Access Token
              </label>
              <input
                type="password"
                value={token}
                onChange={(e) => setToken(e.target.value)}
                placeholder="ghp_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"
                className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:border-accent focus:ring-2 focus:ring-accent/10 font-mono"
              />
              <p className="text-[10px] text-text-muted mt-1.5">
