                  {status.lastBackupError}
                </p>
              </div>
            </div>
          )}

          {/* Push queue warning */}
          {status.pendingQueue > 0 && (
            <div className="bg-amber-500/5 border border-amber-500/20 rounded-xl px-4 py-3 flex items-start gap-3">
