app.post('/api/backup/retry-push', rateLimit('write'), async (req, res) => {
  try {
    const result = await backup.retryPush();
    if (!result.ok) return res.status(400).json(result);
    res.json(result);
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Tail structured backup logs (for debugging UI)
app.get('/api/backup/logs', rateLimit('read'), (req, res) => {
  try {
    const lines = Math.min(parseInt(req.query.lines) || 200, 1000);
    res.json(backup.tailLog(lines));
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

